{
  "status": "SUPPORTED",
  "task_summary": "The robot must identify compatible components for a fastening task at a workbench, perform the fastening, and place the equipment back on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the task occurs and equipment is placed.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["wooden desk", "table"],
      "required_properties": ["stable", "flat"]
      },
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location on the workbench requiring repair.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["marked location", "repair site"],
      "required_properties": ["needs fastening", "accessible"]
      },
      {
        "id": "compatible_components",
        "entity_kind": "OBJECT",
        "function": "Parts needed to fix the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["parts", "blocks", "hardware"],
      "required_properties": ["fits target", "compatible"]
      },
      {
        "id": "fastening_equipment",
        "entity_kind": "OBJECT",
        "function": "Tool used to perform the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["tool", "wrench", "screwdriver"],
      "required_properties": ["usable for fastening", "reusable"]
      }
    ],
    "functional_relations": [
      {
        "id": "compatibility",
        "relation": "compatible_components fit fastening_target",
        "participant_roles": ["compatible_components", "fastening_target"]
      ,
      "required": true
      },
      {
        "id": "usage",
        "relation": "fastening_equipment used_on fastening_target",
        "participant_roles": ["fastening_equipment", "fastening_target"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "identify_and_select_components",
        "operation": "identify_and_select_compatible_components",
        "participant_roles": ["compatible_components", "workbench"],
        "operation_count": 1
      },
      {
        "id": "apply_fastening",
        "operation": "complete_fastening",
        "participant_roles": ["fastening_equipment", "fastening_target", "compatible_components"],
        "operation_count": 1
      },
      {
        "id": "cleanup",
        "operation": "place_equipment",
        "participant_roles": ["fastening_equipment", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        {
          "label": "wooden desk",
          "visual_description": "Wooden table with drawers and a cabinet on top."
        }
      ],
      "fastening_target": [
        {
          "label": "tray on desk",
          "visual_description": "Black tray with yellow and blue blocks on the desk surface."
        }
      ],
      "compatible_components": [
        {
          "label": "yellow/blue blocks on tray",
          "visual_description": "Rectangular objects on the black tray."
        }
      ],
      "fastening_equipment": [
        {
          "label": "tool held by robot arm",
          "visual_description": "Yellow object held by the white robot arm in the third image."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue cabinet",
        "visual_description": "Tall blue cabinet behind the desk.",
        "reason": "Closed storage structure potentially containing tools or components."
      },
      {
        "id": "left_drawer",
        "label": "left drawer",
        "visual_description": "Left drawer under the desk.",
        "reason": "Closed storage structure potentially containing tools or components."
      },
      {
        "id": "right_drawer",
        "label": "right drawer",
        "visual_description": "Right drawer under the desk.",
        "reason": "Closed storage structure potentially containing tools or components."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
